mapper.select:
select count(distinct l.client_ip)
from biz_access_log l


        inner join biz_query q on q.query_id = l.target_id
        and q.create_user_id = #{createUserId}


        inner join biz_survey s on s.survey_id = l.target_id
        and s.create_user_id = #{createUserId}


where l.target_type = #{targetType}
  and l.action = #{action}
  and l.client_ip is not null
  and l.client_ip <> ''

  and l.create_time >= current_date

select log_id, target_type, target_id, public_code, action, client_ip, user_agent, detail_json, channel_code, create_time
from biz_access_log
where target_type = #{targetType}
  and target_id = #{targetId}

  and action = #{action}

order by create_time desc, log_id desc
limit #{limit}

select count(distinct client_ip)
from biz_access_log
where target_type = #{targetType}
  and target_id = #{targetId}
  and action = #{action}
  and client_ip is not null and client_ip <> ''

select action as "action",
       count(*)::bigint as "events",
       count(distinct client_ip)::bigint as "uv"
from biz_access_log
where target_type = #{targetType}
  and target_id = #{targetId}
  and action in
  #{a}
group by action

select coalesce(nullif(trim(channel_code), ''), '(默认)') as "channelCode",
       count(distinct client_ip)::bigint as "viewUv"
from biz_access_log
where target_type = #{targetType}
  and target_id = #{targetId}
  and action = #{action}
group by coalesce(nullif(trim(channel_code), ''), '(默认)')
